const fs = require('fs');
const path = require('path');

// Read last 1 minute of logs
const logsDir = '/path/to/logs';
const now = new Date();
const oneMinuteAgo = new Date(now.getTime() - 60000);

let recentLogs = [];
const files = fs.readdirSync(logsDir);

files.forEach(file => {
  const filePath = path.join(logsDir, file);
  const content = fs.readFileSync(filePath, 'utf8').split('\n');

  content.forEach(line => {
    if (!line.trim()) return;
    try {
      const log = JSON.parse(line);
      const logTime = new Date(log.timestamp);
      if (logTime >= oneMinuteAgo && logTime <= now) {
        recentLogs.push(log);
      }
    } catch (e) {
      // Skip invalid JSON
    }
  });
});

return [{ json: { logs: recentLogs, count: recentLogs.length } }];

const logs = $node['Read Recent Logs'].json.logs;
const errors = logs.filter(log => log.level === 'ERROR');

return [{
  json: {
    errors: errors,
    error_count: errors.length,
    has_errors: errors.length > 0
  }
}];

const logs = $node['Read Recent Logs'].json.logs;
const slowOps = logs.filter(log => 
  log.data && log.data.duration_ms > 1000
);

// Group by message
const grouped = {};
slowOps.forEach(log => {
  if (!grouped[log.message]) {
    grouped[log.message] = [];
  }
  grouped[log.message].push(log);
});

return [{
  json: {
    slow_operations: slowOps,
    slow_count: slowOps.length,
    grouped_by_type: grouped,
    has_slow_ops: slowOps.length > 0
  }
}];

const logs = $node['Read Recent Logs'].json.logs;
const grades = {};
let totalGrades = 0;

logs.forEach(log => {
  if (log.message === 'Grade calculated' && log.data && log.data.grade) {
    const grade = log.data.grade;
    grades[grade] = (grades[grade] || 0) + 1;
    totalGrades++;
  }
});

const distribution = {};
Object.keys(grades).forEach(grade => {
  distribution[grade] = {
    count: grades[grade],
    percentage: ((grades[grade] / totalGrades) * 100).toFixed(2)
  };
});

return [{
  json: {
    grade_distribution: distribution,
    total_grades: totalGrades,
    expected_range: {
      '강매': '5-10%',
      '급등': '10-15%',
      '매도차익': '20-30%',
      '기타': '50-70%'
    }
  }
}];

const logs = $node['Read Recent Logs'].json.logs;
const requestIds = {};

logs.forEach(log => {
  const rid = log.request_id;
  if (!requestIds[rid]) {
    requestIds[rid] = [];
  }
  requestIds[rid].push({
    timestamp: log.timestamp,
    service: log.service,
    message: log.message
  });
});

const flows = {};
Object.keys(requestIds).forEach(rid => {
  flows[rid] = {
    steps: requestIds[rid].length,
    services: [...new Set(requestIds[rid].map(s => s.service))],
    sequence: requestIds[rid].map(s => s.message)
  };
});

return [{
  json: {
    request_flows: flows,
    total_flows: Object.keys(flows).length,
    trace_valid: Object.keys(flows).every(rid => 
      flows[rid].services.length > 0
    )
  }
}];

const errors = $node['Detect Errors'].json;
const slowOps = $node['Detect Slow Operations'].json;
const grades = $node['Check Grade Distribution'].json;
const flows = $node['Verify Request ID Propagation'].json;
const logs = $node['Read Recent Logs'].json.logs;

const status = {
  timestamp: new Date().toISOString(),
  summary: {
    total_logs: logs.length,
    errors: errors.error_count,
    slow_operations: slowOps.slow_count,
    request_flows: flows.total_flows,
    trace_valid: flows.trace_valid
  },
  alerts: [],
  recommendations: []
};

// Check for alerts
if (errors.error_count > 0) {
  status.alerts.push({
    severity: 'CRITICAL',
    type: 'ERRORS_DETECTED',
    count: errors.error_count,
    details: errors.errors.slice(0, 3) // First 3 errors
  });
}

if (slowOps.slow_count > 3) {
  status.alerts.push({
    severity: 'WARNING',
    type: 'SLOW_OPERATIONS',
    count: slowOps.slow_count,
    avg_duration: Math.round(
      slowOps.slow_operations.reduce((sum, op) => sum + op.data.duration_ms, 0) / slowOps.slow_count
    )
  });
}

if (!flows.trace_valid) {
  status.alerts.push({
    severity: 'WARNING',
    type: 'REQUEST_TRACE_ISSUE',
    message: 'Some request flows may be incomplete'
  });
}

// Recommendations
if (errors.error_count === 0) {
  status.recommendations.push('✓ No errors detected');
} else {
  status.recommendations.push('Review and fix detected errors');
}

if (slowOps.slow_count < 3) {
  status.recommendations.push('✓ Performance within acceptable range');
} else {
  status.recommendations.push('Investigate slow operations for optimization');
}

status.recommendations.push(`Grade distribution tracked: ${Object.keys(grades.grade_distribution).length} types`);
status.recommendations.push(`Request tracing: ${flows.total_flows} flows verified`);

return [{ json: status }];

const report = $node['Compile QA Report'].json;
const fs = require('fs');
const path = require('path');

const qaLogsDir = '/path/to/qa-logs';
if (!fs.existsSync(qaLogsDir)) {
  fs.mkdirSync(qaLogsDir, { recursive: true });
}

const date = new Date().toISOString().split('T')[0];
const time = new Date().toISOString().split('T')[1].split('.')[0].replace(/:/g, '');
const filename = `qa-report-${date}_${time}.json`;
const filepath = path.join(qaLogsDir, filename);

fs.writeFileSync(filepath, JSON.stringify(report, null, 2));

return [{
  json: {
    logged: true,
    file: filename,
    summary: report.summary,
    alerts_count: report.alerts.length
  }
}];

const fs = require('fs');
const path = require('path');

const logsDir = '/path/to/logs';
const date = new Date().toISOString().split('T')[0];

let dailyStats = {
  date: date,
  total_logs: 0,
  errors: 0,
  warnings: 0,
  info: 0,
  debug: 0,
  slow_operations: 0,
  avg_duration_ms: 0,
  grade_distribution: {},
  services: {},
  error_details: []
};

const files = fs.readdirSync(logsDir);
let totalDuration = 0;
let durationCount = 0;

files.forEach(file => {
  if (!file.includes(date)) return;

  const filePath = path.join(logsDir, file);
  const content = fs.readFileSync(filePath, 'utf8').split('\n');

  content.forEach(line => {
    if (!line.trim()) return;
    try {
      const log = JSON.parse(line);
      dailyStats.total_logs++;

      // Count by level
      if (log.level === 'ERROR') dailyStats.errors++;
      else if (log.level === 'WARNING') dailyStats.warnings++;
      else if (log.level === 'INFO') dailyStats.info++;
      else if (log.level === 'DEBUG') dailyStats.debug++;

      // Slow operations
      if (log.data && log.data.duration_ms > 1000) {
        dailyStats.slow_operations++;
      }

      // Duration tracking
      if (log.data && log.data.duration_ms) {
        totalDuration += log.data.duration_ms;
        durationCount++;
      }

      // Grade distribution
      if (log.message === 'Grade calculated' && log.data && log.data.grade) {
        dailyStats.grade_distribution[log.data.grade] = 
          (dailyStats.grade_distribution[log.data.grade] || 0) + 1;
      }

      // Service stats
      if (!dailyStats.services[log.service]) {
        dailyStats.services[log.service] = 0;
      }
      dailyStats.services[log.service]++;

      // Error details (first 10)
      if (log.level === 'ERROR' && dailyStats.error_details.length < 10) {
        dailyStats.error_details.push({
          timestamp: log.timestamp,
          message: log.message,
          request_id: log.request_id
        });
      }
    } catch (e) {
      // Skip invalid JSON
    }
  });
});

if (durationCount > 0) {
  dailyStats.avg_duration_ms = (totalDuration / durationCount).toFixed(2);
}

return [{ json: dailyStats }];

