const errors = $node['Detect Errors'].json.errors;

if (errors.length === 0) {
  return [{ json: { created: false, reason: 'No errors to report' } }];
}

const issueDate = new Date().toISOString().split('T')[0];
const firstError = errors[0];

const issue = {
  id: `ISSUE-${Date.now()}`,
  date: issueDate,
  title: `${firstError.message} - ${firstError.service}`,
  severity: 'CRITICAL',
  request_id: firstError.request_id,
  service: firstError.service,
  error_count: errors.length,
  first_error: firstError,
  summary: `${errors.length} error(s) detected in ${firstError.service}`,
  status: 'NEW'
};

return [{ json: issue }];
